# Hypothesis 2: Make enclosed regions 6, rest stay 3
# Use flood fill from borders to find what's "outside"

def flood_fill_outside(grid):
    n, m = len(grid), len(grid[0])
    visited = [[False]*m for _ in range(n)]
    output = [[0]*m for _ in range(n)]

    # Start flood fill from all border cells with value 3
    from collections import deque
    queue = deque()
    for i in range(n):
        if grid[i][0] == 3:
            queue.append((i, 0))
        if grid[i][m-1] == 3:
            queue.append((i, m-1))
    for j in range(m):
        if grid[0][j] == 3:
            queue.append((0, j))
        if grid[n-1][j] == 3:
            queue.append((n-1, j))

    while queue:
        i, j = queue.popleft()
        if visited[i][j]:
            continue
        visited[i][j] = True
        output[i][j] = 3  # outside stays 3
        for di, dj in [(0,1), (0,-1), (1,0), (-1,0)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < m and not visited[ni][nj] and grid[ni][nj] == 3:
                queue.append((ni, nj))

    # Everything not visited is "inside" - it should be 6
    for i in range(n):
        for j in range(m):
            if not visited[i][j]:
                output[i][j] = 6

    # Keep the 6s
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 6:
                output[i][j] = 6

    return output

